export type UpdateStatus = { effective_plugins_catalog_url?: string, available_catalogs: Array<PluginCatalog>, host_os: string, host_arch: string, plugin_updates: Array<PluginUpdate>, plugin_policy_error?: string, installed_manager: string, preferences: UpdatePreferences, manager: CheckState, plugins: CheckState, jobs: Array<UpdateJob>, };
